  &reftitle.description;

   arrayarray_reverse
   arrayarray
   boolpreserve_keys&false;


एउटा input array लिन्छ र elements को क्रम उल्ट्याएर नयाँ array return गर्दछ।

  &reftitle.examples;



    array_reverse को उदाहरण


<?php
$input  = array("php", 4.0, array("green", "red"));
$reversed = array_reverse($input);
$preserved = array_reverse($input, true);

print_r($input);
print_r($reversed);
print_r($preserved);
?>


